package com.emssystem.emsleaveservice.pto.entity; import com.emssystem.emsleaveservice.shared.entity.AuditableEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="pto_types",uniqueConstraints=@UniqueConstraint(name="uk_pto_type_name",columnNames="name")) public class PtoType extends AuditableEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=100) private String name;@Column(name="accrual_rate_per_period",nullable=false,precision=10,scale=4) private BigDecimal accrualRatePerPeriod;@Column(name="max_carryover",nullable=false,precision=10,scale=2) private BigDecimal maxCarryover;@Column(nullable=false) private boolean paid;protected PtoType(){}public PtoType(String name,BigDecimal rate,BigDecimal max,boolean paid){this.name=name;this.accrualRatePerPeriod=rate;this.maxCarryover=max;this.paid=paid;}public Long getId(){return id;}public String getName(){return name;}public BigDecimal getAccrualRatePerPeriod(){return accrualRatePerPeriod;}public BigDecimal getMaxCarryover(){return maxCarryover;}public boolean isPaid(){return paid;}}
